"""Explain expected storage, wrapper families and generic macro pointer evaluation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1593': ('숫자판과 “내가 예상한 숫자”를 적은 메모가 있어요. 비교 교체에서는 숫자판뿐 아니라 그 메모도 읽고 고칠 수 있어서 두 위치를 따로 보고해요.', '자료형별 try_cmpxchg에서 대상과 예상 값 메모의 보고를 구별합니다.', '대상 v=5, 별도 메모 old=4를 그리세요. 각각에 주소·크기 보고 화살표를 붙이고 실패 뒤 메모가 5가 된다고 적으세요.', ['자료형별 함수란 atomic_try_cmpxchg나 atomic_long_try_cmpxchg처럼 다룰 원자 자료형이 이름과 선언에 정해진 함수를 말해요. table의 인자 명세는 대상 v, 예상 값 위치 p:old, 새 숫자 i:new예요.', 'p는 정수의 위치를 가리키는 포인터 분류예요. old는 비교 기준을 담은 메모의 이름이에요. 원자 대상 v와 메모 old는 역할이 다르고, 정상 사용에서는 각각 올바른 저장 공간을 전달해야 해요.', 'gen_param_check는 p:old가 값 i도 아니고 읽기 전용 포인터도 아니며 이 함수가 단순 store도 아니므로 read_write로 골라요. 이 typed 생성 경로에서는 instrument_atomic_read_write를 출력해요.', '따라서 v, sizeof(*v)를 보고한 뒤 old, sizeof(*old)도 별도로 보고해요. 이름 old라고 해서 v의 주소를 다시 보고하는 것이 아니에요. 각 인자에 전달한 위치와 그 대상 크기를 사용해요.', '실제 5·예상 4로 비교 교체하면 대상은 5를 유지하고 old 메모는 관찰한 5로 바뀔 수 있어요. 이 동작은 raw 연산의 약속이에요. 앞의 hook은 접근을 보고하며 스스로 이 계산을 대신하지 않아요.', 'hook 이름에 atomic이 있어도 old 메모를 여러 작업이 아무 보호 없이 함께 써도 된다는 허가는 아니에요. 메모의 수명과 공유 규칙은 따로 지켜야 해요. 다음에 볼 generic try 매크로는 old에 다른 종류의 hook을 쓰므로 경로도 구별하세요.'], [('자료형별 atomic_try_cmpxchg에서 p:old에 생성하는 hook은 무엇인가요?', ['아무 hook도 만들지 않아요', 'instrument_atomic_read_write를 만들어요'], '정답은 두 번째예요. 이 생성 경로는 수정 가능한 포인터이고 store가 아니면 read_write로 분류해요. 실제 인자 위치 old를 따로 보고해요.'), ('대상 v와 예상 값 포인터 old는 이름 때문에 같은 보고 주소로 처리되나요?', ['아니요. 각 인자로 전달한 저장 공간을 각각 보고해요', '네. old라는 이름이면 언제나 v 주소를 다시 보고해요'], '정답은 첫 번째예요. 생성 표현은 v, sizeof(*v)와 old, sizeof(*old)로 나뉘어요. 숫자판과 예상 메모의 역할을 구별하세요.')]), 'os1594': ('같은 문제 양식을 작은 숫자용·큰 숫자용·환경에 맞는 숫자용으로 만들 수 있어요. 규칙을 공유하되 자료형 이름을 바꾸어 여러 함수 계열을 생성해요.', '공통 표를 세 자료형 계열로 펼치는 방법과 검증 범위를 이해합니다.', 'atomic/int, atomic64/s64, atomic_long/long의 세 칸에 각각 85를 적고 85×3=255를 계산하세요.', ['계측 생성기는 atomics.tbl을 세 차례 읽어요. 첫째는 atomic과 int, 둘째는 atomic64와 s64, 셋째는 atomic_long과 long이라는 이름 조합을 전달해요.', '같은 read 행도 계열에 따라 atomic_read, atomic64_read, atomic_long_read가 돼요. 인자와 반환 타입도 해당 계열에 맞게 만들어져요. 한 표로 비슷한 함수들의 규칙을 함께 관리하는 방법이에요.', '각 계열은 순서 형태까지 펼쳐 85개 wrapper를 만들어요. 그래서 typed wrapper의 합은 85+85+85=255개예요. 별도로 만드는 generic exchange 매크로까지 이 숫자에 섞어 세면 안 돼요.', '함수 생성은 주석, 타입과 이름의 선언, 접근 검사, raw 호출 순서로 이어져요. void 함수에는 반환값이 없고 bool이나 정수 함수에는 결과를 돌려주는 문장이 필요해요. 공통 도우미가 이 차이를 반영해요.', '컴파일은 코드를 기계가 실행할 형태로 번역하고 정해진 문법·타입 조건을 확인하는 과정이에요. 255개를 컴파일했다고 255개를 모두 호출했다는 뜻은 아니에요. 컴파일만으로 모든 입력과 조건 분기가 실행되지는 않아요.', '실행 검사를 했다면 어떤 함수를 어떤 입력으로 호출했는지 따로 적어야 해요. 예를 들어 선택한 일부 사례가 맞아도 나머지 모든 경우가 검증된 것은 아니에요. 이 수업은 생성 수와 검사 범위를 구별하며 과거 실행 수치를 새 실행 결과처럼 주장하지 않아요.'], [('85개 API 형태를 atomic·atomic64·atomic_long에 각각 펼치면 typed wrapper는 모두 몇 개인가요?', ['한 계열만 있으므로 85개예요', '85개씩 세 계열이라 255개예요'], '정답은 두 번째예요. 같은 표를 자료형 이름을 바꾸어 세 번 적용해요. 이 수에는 별도로 생성하는 generic 매크로를 더하지 않았어요.'), ('255개 wrapper를 컴파일했다면 모든 함수의 모든 입력을 실행한 것인가요?', ['아니요. 실제 호출한 함수와 입력은 별도로 확인해야 해요', '네. 컴파일하면 모든 실행 분기가 자동으로 수행돼요'], '정답은 첫 번째예요. 번역과 실행은 다른 단계예요. 컴파일 성공은 모든 입력의 결과나 모든 경쟁 상황까지 맞는다는 증거가 아니에요.')]), 'os1595': ('주소를 찾는 사람에게 한 번 물어보고 메모해 두면 같은 주소를 다시 사용할 수 있어요. 매크로도 주소 식을 여러 번 계산하지 않도록 지역 변수에 담아요.', '일반 고정 타입 포인터 식의 한 번 평가와 GNU 매크로 문법을 이해합니다.', '주소를 돌려주는 get_ptr() → __ai_ptr 저장 → hook과 raw에서 __ai_ptr 재사용의 그림을 그리세요.', ['매크로는 호출한 위치에 코드 모양을 펼치는 규칙이에요. 함수처럼 보이더라도 입력 식을 여러 곳에 그대로 반복해 쓰면 부수 효과가 여러 번 일어날 수 있어요. 부수 효과는 호출 횟수 증가처럼 값 계산 외에 상태가 바뀌는 일이에요.', 'gen_xchg가 만드는 매크로는 ({ ... })라는 GNU statement expression을 써요. 여러 문장을 실행하면서 마지막 표현의 값을 결과로 쓸 수 있는 확장 문법이에요. 모든 표준 C 환경에서 그대로 쓰는 문법은 아니에요.', '그 안의 typeof(ptr) __ai_ptr = (ptr)는 입력과 맞는 포인터 타입의 지역 변수에 주소를 저장해요. 보통의 고정 타입 포인터라면 typeof는 타입을 알아보고 실제 ptr 식의 평가는 초기화에서 한 번 해요.', '예를 들어 get_ptr()가 호출 횟수를 늘리고 int 포인터를 돌려준다면, 이 일반 사용에서 주소 계산은 한 번 하고 결과를 __ai_ptr에 담아요. hook과 raw 호출은 get_ptr()를 다시 쓰지 않고 __ai_ptr를 재사용해요.', 'generic try 갈래는 oldp도 __ai_oldp에 저장해 똑같이 재사용해요. 두 입력 식이 각각 한 번 평가된다는 설명이지 두 위치가 같은 자료라는 뜻은 아니에요. 대상 포인터와 예상 값 메모 포인터를 구별하세요.', 'typeof가 모든 상황에서 무조건 아무 식도 평가하지 않는다고 외우지는 마세요. 실행 중 크기가 정해지는 배열과 관련된 타입 등은 별도 언어 규칙이 있어요. 여기의 설명 범위는 int *처럼 보통의 고정 타입 포인터예요.'], [('get_ptr()가 보통의 int 포인터를 돌려줘요. generic try 한 호출에서 이 주소 식은 몇 번 실제 평가되나요?', ['hook과 raw가 각각 호출하므로 언제나 두 번이에요', '지역 포인터에 담고 재사용하므로 한 번이에요'], '정답은 두 번째예요. 초기화에서 얻은 주소를 __ai_ptr에 보관해 두 곳에서 써요. 같은 입력 식을 두 번 계산하는 것과 달라요.'), ('typeof는 모든 타입과 모든 C 확장에서 예외 없이 식을 평가하지 않는다고 말해도 되나요?', ['아니요. 여기의 고정 타입 포인터 범위와 다른 타입 규칙을 구별해야 해요', '네. 어떤 타입 문맥에서도 예외가 없어요'], '정답은 첫 번째예요. 이 예시의 한 번 평가 규칙을 모든 타입에 확대하면 안 돼요. 변동하는 크기와 관련된 타입 등은 해당 언어 규칙을 따로 확인해야 해요.')]), 'os1596': ('같은 비교 교체라도 대상 숫자판과 예상 메모를 기록하는 칸의 이름이 다를 수 있어요. 이 매크로에서는 두 저장 공간에 서로 다른 보고 함수를 붙여요.', 'generic try와 typed try의 예상 값 접근 보고를 구별합니다.', 'generic try: 대상 → instrument_atomic_read_write, 예상 메모 → instrument_read_write의 두 화살표를 그리세요.', ['generic try 매크로는 ptr를 __ai_ptr에, oldp를 __ai_oldp에 담아요. generic은 특정 atomic_t 이름만으로 고정된 함수와 다른 일반 매크로 경로라는 뜻으로 읽으면 돼요.', '대상 __ai_ptr에는 instrument_atomic_read_write를 호출해요. 원자적으로 비교하고 교체하려는 대상 위치의 접근을 알리는 부분이에요. 크기는 sizeof(*__ai_ptr)로 전달해요.', '예상 값 메모 __ai_oldp에는 atomic이라는 단어가 없는 instrument_read_write를 호출해요. 크기는 sizeof(*__ai_oldp)예요. 이 경로에서는 대상과 메모의 hook 이름이 실제로 다르게 적혀 있어요.', '자료형별 atomic_try_cmpxchg wrapper에서는 old에 instrument_atomic_read_write를 생성했어요. 그 사실을 generic try 매크로에 그대로 옮기면 틀려요. 비슷한 이름이어도 지금 보고 있는 생성 경로를 확인해야 해요.', '대상 5·예상 메모 4·새 값 9라면 raw 비교가 실패해 대상은 5를 유지하고 메모는 관찰한 5로 바뀔 수 있어요. 예상 메모가 읽기뿐 아니라 쓰기 접근도 받을 수 있어 별도 보고가 필요한 이유예요.', '접근 보고 함수 이름이 메모의 수명이나 안전한 공동 사용을 보장하지는 않아요. 특히 여러 작업이 예상 메모를 함께 쓰려면 별도 동기화 규칙이 필요해요. 보고 분류, 실제 raw 동작, 자료 보호를 나누어 읽으세요.'], [('generic try 매크로의 예상 메모 oldp에는 어떤 hook을 사용하나요?', ['무조건 instrument_atomic_read_write만 사용해요', 'instrument_read_write를 사용해요'], '정답은 두 번째예요. 원문은 대상에는 atomic이 있는 이름, 예상 메모에는 atomic이 없는 이름을 적어요. 자료형별 함수 경로와 혼동하지 마세요.'), ('generic try 비교가 실패하면 예상 메모는 어떻게 될 수 있나요?', ['관찰한 현재 대상 값으로 바뀔 수 있어요', '항상 그대로이고 어떤 접근도 하지 않아요'], '정답은 첫 번째예요. 대상이 5인데 메모가 4라면 대상은 유지하면서 메모를 5로 고쳐 줄 수 있어요. 두 저장 공간의 결과를 따로 보세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_394.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
